1	// MIA 2.0 Glass-Box — Keyboard Shortcuts globais.
2	//
3	// Atalhos suportados:
4	//   Ctrl+M (Cmd+M no Mac) → toggle Modo IA
5	//   Esc                   → fecha highlight ativo (quando há um)
6	//
7	// Monta em DashboardLayout. Ignora eventos vindos de input/textarea/contenteditable
8	// pra não interferir com digitação normal.
9	//
10	// Doc: docs/mia/ARCHITECTURE.md (Section 9.2)
11	
12	import { useEffect } from 'react';
13	import { useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
14	import { usePermissions } from '@/shared/hooks/usePermissions';
15	
16	function isTypingTarget(el: EventTarget | null): boolean {
17	  if (!(el instanceof HTMLElement)) return false;
18	  const tag = el.tagName;
19	  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return true;
20	  if (el.isContentEditable) return true;
21	  // shadcn Combobox / cmd-k popovers
22	  if (el.closest('[role="combobox"]') || el.closest('[role="dialog"]')) {
23	    return tag === 'INPUT' || tag === 'TEXTAREA';
24	  }
25	  return false;
26	}
27	
28	export function useMiaKeyboardShortcuts() {
29	  const { toggleMiaMode, currentHighlight, clearHighlight } = useMiaGlassBoxContext();
30	  const { canViewMia } = usePermissions();
31	
32	  useEffect(() => {
33	    if (!canViewMia()) return;
34	
35	    function onKey(e: KeyboardEvent) {
36	      // Ctrl+M (Win/Linux) ou Cmd+M (Mac) → toggle Modo IA
37	      if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === 'm') {
38	        if (isTypingTarget(e.target)) return;
39	        e.preventDefault();
40	        toggleMiaMode();
41	        return;
42	      }
43	
44	      // Esc → limpa highlight se houver
45	      if (e.key === 'Escape' && currentHighlight) {
46	        clearHighlight();
47	      }
48	    }
49	
50	    window.addEventListener('keydown', onKey);
51	    return () => window.removeEventListener('keydown', onKey);
52	  }, [canViewMia, toggleMiaMode, currentHighlight, clearHighlight]);
53	}
