1	import { useState, useCallback, useRef, useEffect } from "react";
2	import { useMiaPageContext } from "@/features/mia/hooks/useMiaPageContext";
3	import { ArrowDownCircle, ArrowUpCircle, QrCode, Camera, Bluetooth, Loader2, Package, Trash2, AlertCircle, CheckCircle2, PackageOpen, History } from "lucide-react";
4	import { Link } from "react-router-dom";
5	import { Button } from "@/shared/ui/button";
6	import { Badge } from "@/shared/ui/badge";
7	import { Card, CardContent } from "@/shared/ui/card";
8	import { supabase } from "@/integrations/supabase/client";
9	import { useToast } from "@/shared/ui/use-toast";
10	import { handleError } from '@/shared/lib/error-handler';
11	import { useStore } from "@/shared/contexts/StoreContext";
12	import { DashboardLayout } from "@/features/dashboard/ui/DashboardLayout";
13	import { clsx } from "clsx";
14	import {
15	    useEtiquetaScanner,
16	    playSuccessSound,
17	    playErrorSound,
18	    formatBipError,
19	    type ScannedPayload,
20	} from "@/shared/hooks/useEtiquetaScanner";
21	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
22	import { SaidaAvulsaDialog, type EtiquetaContext } from "@/features/logistica/ui/SaidaAvulsaDialog";
23	
24	// Compatibilidade com o resto do componente — alias do tipo do hook
25	type ScannedData = ScannedPayload;
26	
27	interface ProductInfo {
28	    id: number;
29	    nome: string;
30	    foto_url?: string;
31	}
32	
33	interface ScannedItem {
34	    id: string;
35	    rawQr: string;
36	    data: ScannedData;
37	    productInfo?: ProductInfo;
38	    status: 'pending' | 'loading' | 'success' | 'error' | 'duplicate';
39	    error?: string;
40	    /** Status da etiqueta no banco — informativo, não bloqueia contagem */
41	    etiquetaStatus?: string;
42	    /** Snapshot da etiqueta do banco — usado pelo modal de saída avulsa */
43	    etiqueta?: {
44	        quantidade_interna: number;
45	        quantidade_disponivel: number;
46	        tipo_embalagem: string | null;
47	        embalagem_nome: string | null;
48	        lote_codigo: string | null;
49	    };
50	}
51	
52	// Sons centralizados em useEtiquetaScanner — playSuccessSound/playErrorSound importados.
53	
54	export function ScannerContent() {
55	    const { toast } = useToast();
56	    const { selectedStore } = useStore();
57	
58	    const [scannedItems, setScannedItems] = useState<ScannedItem[]>([]);
59	    const [isProcessing, setIsProcessing] = useState(false);
60	    // Dedup local via ref pra evitar race condition (callback de setState
61	    // não é confiável pra ler estado síncrono em React 18 concurrent).
62	    const uidsLidosRef = useRef<Set<string>>(new Set());
63	
64	    // Chave do localStorage por loja — filas de lojas diferentes não se misturam.
65	    const queueKey = selectedStore ? `scanner_queue_v1_${selectedStore.id}` : null;
66	
67	    // Restore da fila ao montar (ou ao trocar de loja): itens 'loading' interrompidos
68	    // voltam como 'pending' já que o processamento não chegou a concluir.
69	    useEffect(() => {
70	        if (!queueKey) return;
71	        try {
72	            const raw = localStorage.getItem(queueKey);
73	            if (!raw) return;
74	            const saved: ScannedItem[] = JSON.parse(raw);
75	            const restored = saved.map(i =>
76	                i.status === 'loading' ? { ...i, status: 'pending' as const } : i
77	            );
78	            setScannedItems(restored);
79	            restored.forEach(i => { if (i.data.uid) uidsLidosRef.current.add(i.data.uid); });
80	        } catch { /* localStorage corrompido — ignora, começa limpo */ }
81	    // eslint-disable-next-line react-hooks/exhaustive-deps
82	    }, [queueKey]);
83	
84	    // Persiste a fila a cada mudança.
85	    useEffect(() => {
86	        if (!queueKey) return;
87	        try { localStorage.setItem(queueKey, JSON.stringify(scannedItems)); } catch { /* quota — ignora */ }
88	    }, [scannedItems, queueKey]);
89	    // Modal de saída avulsa — abre ao clicar "Retirar Avulso" num item da lista
90	    const [saidaAvulsaItem, setSaidaAvulsaItem] = useState<EtiquetaContext | null>(null);
91	    const [saidaAvulsaLoading, setSaidaAvulsaLoading] = useState(false);
92	
93	    // Painel de debug — captura TODO scan (sucesso ou falha) pra diagnóstico em campo.
94	    // Sem isso, quando o leitor envia algo estranho (layout BR, chunked, suffix CR),
95	    // não dá pra saber o que chegou — só o sintoma.
96	    // Recebe o payload já parseado/sanitizado/dedupe-cooldown pelo hook.
97	    // Decisão arquitetônica: PC usa Bluetooth/USB (estável), tablet usa Câmera
98	    // (Chrome Android tem bug WontFix de keydown). Câmera entrega o QR completo
99	    // num único callback, sem perda. Não precisamos mais de lookup reverso ou
100	    // resolução de UID por pid+lote — fluxo é direto.
101	    const handleScan = useCallback(async (data: ScannedPayload) => {
102	        if (!data.uid) {
103	            playErrorSound();
104	            if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
105	            toast({
106	                title: "QR não reconhecido",
107	                description: "Etiqueta inválida ou não é da Momma.",
108	                variant: "destructive",
109	            });
110	            return;
111	        }
112	
113	        const dedupKey = data.uid;
114	
115	        // CAMADA 1 — dedup via ref (síncrono, não tem race com setState).
116	        if (uidsLidosRef.current.has(dedupKey)) {
117	            playErrorSound();
118	            toast({
119	                title: "Caixa já lida!",
120	                description: "Esta etiqueta já está na lista atual.",
121	                variant: "destructive",
122	            });
123	            if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
124	            return;
125	        }
126	        uidsLidosRef.current.add(dedupKey);
127	
128	        // Adiciona à lista visual
129	        setScannedItems(prev => [
130	            {
131	                id: Date.now().toString() + Math.random().toString(36).substring(7),
132	                rawQr: dedupKey,
133	                data: { ...data, qty: data.qty || 1 },
134	                status: 'loading' as const,
135	            },
136	            ...prev,
137	        ]);
138	
139	        // CAMADA 2 — banco: lookup completo da etiqueta pelo UID.
140	        // QR carrega APENAS o UID (formato canônico atual) — todos os dados
141	        // (produto, lote, validade, qty, embalagem) vivem em etiquetas_qr.
142	        // Esse SELECT também pega bips repetidos (status != 'gerada') e popula
143	        // os campos faltantes em `data` pra etiquetas modernas (UID-only).
144	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
145	        const { data: etiqueta } = await (supabase.from('etiquetas_qr' as any) as any)
146	            .select('status, produto_master_id, lote_id, lote_codigo_snapshot, lote_validade_snapshot, embalagem_nome, quantidade_interna, quantidade_disponivel, consumida_inteira, tipo_embalagem, produto_nome_snapshot, loja_atual_id')
147	            .eq('uid', data.uid)
148	            .maybeSingle();
149	
150	        // NÃO bloqueia por status aqui — Scanner é contagem/auditoria geral,
151	        // não é fluxo de separação ou conferência. Se o operador quer ver o
152	        // que tem em mãos, ele escaneia e vê. O status aparece como badge
153	        // informativo no card. Quando processar em lote (entrada/saída) o
154	        // bipar_etiqueta valida a transição correta.
155	
156	        // Popular `data` com snapshots do banco quando QR carrega só UID.
157	        // Mantém prioridade pro QR se ele já tinha os campos (fallback legacy).
158	        const enrichedData: ScannedPayload = {
159	            ...data,
160	            pid: data.pid || String(etiqueta?.produto_master_id ?? ""),
161	            // Prioriza o lote_id da LINHA da etiqueta (vínculo vivo) sobre o lid do
162	            // QR, que pode apontar pra um lote já deletado (duplicado/limpo depois).
163	            lid: String(etiqueta?.lote_id ?? data.lid ?? ""),
164	            lote: data.lote || String(etiqueta?.lote_codigo_snapshot ?? ""),
165	            emb: data.emb || String(etiqueta?.embalagem_nome ?? ""),
166	            qty: data.qty || Number(etiqueta?.quantidade_interna ?? 1),
167	        };
168	
169	        if (!enrichedData.pid) {
170	            playErrorSound();
171	            toast({
172	                title: "Etiqueta não cadastrada",
173	                description: "Esta UID não existe em etiquetas_qr. Pode ser etiqueta antiga ou de outro sistema.",
174	                variant: "destructive",
175	            });
176	            uidsLidosRef.current.delete(dedupKey);
177	            setScannedItems(prev => prev.filter(i => i.data.uid !== dedupKey));
178	            return;
179	        }
180	
181	        // Atualiza item com dados enriquecidos + snapshot da etiqueta (pra modal saída avulsa).
182	        // Etiqueta legacy NUNCA bipada (sem row no banco) cria snapshot virtual usando
183	        // dados do QR — assim o botão de saída avulsa aparece e a RPC faz backfill ao
184	        // confirmar (recebe payload via item.data).
185	        setScannedItems(prev => prev.map(item =>
186	            item.data.uid === dedupKey
187	                ? {
188	                    ...item,
189	                    data: enrichedData,
190	                    etiquetaStatus: etiqueta?.status ?? 'gerada',
191	                    etiqueta: etiqueta ? {
192	                        quantidade_interna: Number(etiqueta.quantidade_interna ?? 1),
193	                        quantidade_disponivel: Number(etiqueta.quantidade_disponivel ?? etiqueta.quantidade_interna ?? 1),
194	                        tipo_embalagem: etiqueta.tipo_embalagem ?? null,
195	                        embalagem_nome: etiqueta.embalagem_nome ?? null,
196	                        lote_codigo: etiqueta.lote_codigo_snapshot ?? null,
197	                    } : {
198	                        // Snapshot virtual da etiqueta legacy — qty_interna do QR vira capacidade
199	                        // E saldo disponível inicial. RPC faz backfill no primeiro bip de saída/adição.
200	                        quantidade_interna: Number(enrichedData.qty) || 1,
201	                        quantidade_disponivel: Number(enrichedData.qty) || 1,
202	                        tipo_embalagem: 'caixa',
203	                        embalagem_nome: enrichedData.emb || 'un',
204	                        lote_codigo: enrichedData.lote || null,
205	                    },
206	                }
207	                : item
208	        ));
209	
210	        playSuccessSound();
211	        if (navigator.vibrate) navigator.vibrate(100);
212	
213	        // Lookup do produto pra preencher foto na lista
214	        try {
215	            const productInfo = etiqueta?.produto_nome_snapshot
216	                ? { id: etiqueta.produto_master_id, nome: etiqueta.produto_nome_snapshot }
217	                : null;
218	            if (productInfo) {
219	                setScannedItems(prev => prev.map(item =>
220	                    item.rawQr === dedupKey
221	                        ? { ...item, productInfo: productInfo as ProductInfo, status: 'pending' as const }
222	                        : item
223	                ));
224	            }
225	            const { data: product, error } = await supabase
226	                .from('produtos_master')
227	                .select('id, nome, foto_url')
228	                .eq('id', parseInt(enrichedData.pid))
229	                .single();
230	
231	            setScannedItems(prev => prev.map(item =>
232	                item.rawQr === dedupKey
233	                    ? (!error && product
234	                        ? { ...item, productInfo: product as ProductInfo, status: 'pending' as const }
235	                        : { ...item, status: productInfo ? 'pending' as const : 'error' as const, error: productInfo ? undefined : 'Produto não encontrado' })
236	                    : item
237	            ));
238	        } catch (e) {
239	            handleError(e, { domain: 'scanner', operation: 'fetchProduct', showToast: false });
240	            setScannedItems(prev => prev.map(item =>
241	                item.rawQr === dedupKey
242	                    ? { ...item, status: 'error' as const, error: 'Erro ao buscar produto' }
243	                    : item
244	            ));
245	        }
246	    }, [toast]);
247	
248	    // Hook único — Bluetooth + Câmera + cooldown anti-repetição (1.5s) + sanitize
249	    // + fallback de facingMode + diagnóstico de erro real (PR8/PR9).
250	    const scanner = useEtiquetaScanner({
251	        enabled: !isProcessing,
252	        onScan: handleScan,
253	        onDuplicate: () => {
254	            // Câmera/scanner está vendo a mesma caixa de novo dentro da janela
255	            // de cooldown (1.5s). Avisa o operador uma vez sem spammar som de erro.
256	            playErrorSound();
257	            toast({
258	                title: "Caixa já lida!",
259	                description: "Esta etiqueta acabou de ser bipada.",
260	                variant: "destructive",
261	            });
262	            if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
263	        },
264	        onInvalid: () => {
265	            playErrorSound();
266	            toast({
267	                title: "QR não reconhecido",
268	                description: "Etiqueta inválida ou não é da Momma. Tente outra.",
269	                variant: "destructive",
270	            });
271	        },
272	        cameraElementId: "qr-reader",
273	        // PC = Bluetooth (USB scanner estavel). Mobile/tablet = Camera (Chrome
274	        // Android tem bug WontFix de keydown que perde chars em rate alto).
275	        // Detecta via UA — operador pode trocar manualmente se quiser.
276	        initialMode: typeof navigator !== "undefined" && /Android|iPad|iPhone|Mobile|Tablet/i.test(navigator.userAgent)
277	            ? "camera"
278	            : "bluetooth",
279	    });
280	
281	    // Abre modal de saída avulsa pro item bipado
282	    const openSaidaAvulsa = (item: ScannedItem) => {
283	        if (!item.etiqueta || !item.data.uid) {
284	            toast({ title: "Etiqueta não rastreável", description: "Sem dados de container no banco.", variant: "destructive" });
285	            return;
286	        }
287	        setSaidaAvulsaItem({
288	            uid: item.data.uid,
289	            produto_nome: item.productInfo?.nome || 'Produto',
290	            tipo_embalagem: item.etiqueta.tipo_embalagem,
291	            embalagem_nome: item.etiqueta.embalagem_nome,
292	            quantidade_interna: item.etiqueta.quantidade_interna,
293	            quantidade_disponivel: item.etiqueta.quantidade_disponivel,
294	            foto_url: item.productInfo?.foto_url,
295	            lote_codigo: item.etiqueta.lote_codigo,
296	        });
297	    };
298	
299	    // Executa adição avulsa via RPC + movimentação INVERSA (entrada de qtd)
300	    const executarAdicao = async (etiqueta: EtiquetaContext, qtd: number) => {
301	        if (!selectedStore) {
302	            toast({ title: "Atenção", description: "Loja não selecionada.", variant: "destructive" });
303	            return;
304	        }
305	        setSaidaAvulsaLoading(true);
306	        try {
307	            // payload habilita backfill da RPC quando etiqueta legacy nao está no banco
308	            const itemRefBk = scannedItems.find(i => i.data.uid === etiqueta.uid);
309	            // eslint-disable-next-line @typescript-eslint/no-explicit-any
310	            const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)('bipar_devolucao_avulsa', {
311	                p_uid: etiqueta.uid,
312	                p_quantidade: qtd,
313	                p_contexto: {
314	                    loja_id: selectedStore.id,
315	                    referencia_tipo: 'scanner_avulso_adicao',
316	                    payload: itemRefBk?.data ?? null,
317	                },
318	            });
319	            const rpc = rpcRaw as { ok: boolean; erro?: string; quantidade_disponivel?: number } | null;
320	            if (rpcErr || !rpc?.ok) throw new Error(rpc?.erro || rpcErr?.message || 'Falha na adição');
321	
322	            // Movimentação de entrada (espelho da retirada avulsa) — mantém estoque coerente
323	            const itemRef = scannedItems.find(i => i.data.uid === etiqueta.uid);
324	            const pid = itemRef ? parseInt(itemRef.data.pid) : 0;
325	            if (pid > 0) {
326	                const { data: estoqueAtual } = await supabase
327	                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
328	                    .from('estoque' as any)
329	                    .select('quantidade_atual')
330	                    .eq('produto_master_id', pid)
331	                    .eq('loja_id', selectedStore.id)
332	                    .maybeSingle();
333	                // eslint-disable-next-line @typescript-eslint/no-explicit-any
334	                const saldoAnterior: number = (estoqueAtual as any)?.quantidade_atual ?? 0;
335	                const saldoNovo = saldoAnterior + qtd;
336	                // Resolve um lote VIVO pela etiqueta (re-vincula se o do QR foi deletado).
337	                // eslint-disable-next-line @typescript-eslint/no-explicit-any
338	                const { data: loteVivo } = await (supabase.rpc as any)('resolver_lote_etiqueta', { p_uid: etiqueta.uid });
339	                // eslint-disable-next-line @typescript-eslint/no-explicit-any
340	                const { error: movErr } = await (supabase.from('movimentacoes') as any).insert({
341	                    produto_master_id: pid,
342	                    tipo_movimentacao: 'entrada',
343	                    quantidade: qtd,
344	                    quantidade_anterior: saldoAnterior,
345	                    quantidade_nova: saldoNovo,
346	                    motivo: 'adicao_avulsa',
347	                    observacoes: `Adição avulsa de ${qtd} ${etiqueta.embalagem_nome || 'un'} no container — saldo atual ${rpc.quantidade_disponivel} · UID ${etiqueta.uid}`,
348	                    data_movimentacao: new Date().toISOString(),
349	                    loja_id: selectedStore.id,
350	                    lote_id: (loteVivo as string | null) ?? null,
351	                    etiqueta_qr_uid: etiqueta.uid,
352	                });
353	                if (movErr) throw movErr;
354	            }
355	
356	            playSuccessSound();
357	            if (navigator.vibrate) navigator.vibrate(100);
358	            toast({
359	                title: `Adicionados ${qtd} ${etiqueta.embalagem_nome || 'un'}`,
360	                description: `Container agora tem ${rpc.quantidade_disponivel} dentro.`,
361	            });
362	            setScannedItems(prev => prev.map(i =>
363	                i.data.uid === etiqueta.uid
364	                    ? {
365	                        ...i,
366	                        etiqueta: i.etiqueta ? { ...i.etiqueta, quantidade_disponivel: rpc.quantidade_disponivel ?? 0 } : undefined,
367	                        etiquetaStatus: (rpc.quantidade_disponivel === etiqueta.quantidade_interna) ? 'gerada' : 'aberta',
368	                    }
369	                    : i
370	            ));
371	            setSaidaAvulsaItem(null);
372	        } catch (e) {
373	            const msg = (e as Error).message || 'Erro desconhecido';
374	            playErrorSound();
375	            toast({ title: "Falha na adição", description: msg, variant: "destructive" });
376	        } finally {
377	            setSaidaAvulsaLoading(false);
378	        }
379	    };
380	
381	    // Executa retirada (parcial ou inteira) via RPC + movimentação
382	    const executarRetirada = async (etiqueta: EtiquetaContext, qtd: number) => {
383	        if (!selectedStore) {
384	            toast({ title: "Atenção", description: "Loja não selecionada.", variant: "destructive" });
385	            return;
386	        }
387	        setSaidaAvulsaLoading(true);
388	        try {
389	            // Guard estoque agregado: se produto está zerado na loja, não permite retirada
390	            // (evita estoque negativo mesmo quando o container tem saldo fantasma).
391	            const itemRefGuard = scannedItems.find(i => i.data.uid === etiqueta.uid);
392	            const pidGuard = itemRefGuard ? parseInt(itemRefGuard.data.pid) : 0;
393	            if (pidGuard > 0) {
394	                // eslint-disable-next-line @typescript-eslint/no-explicit-any
395	                const { data: estoqueGuard } = await (supabase.from('estoque' as any) as any)
396	                    .select('quantidade_atual')
397	                    .eq('produto_master_id', pidGuard)
398	                    .eq('loja_id', selectedStore.id)
399	                    .maybeSingle();
400	                // eslint-disable-next-line @typescript-eslint/no-explicit-any
401	                const saldoEstoque: number = (estoqueGuard as any)?.quantidade_atual ?? 0;
402	                if (saldoEstoque <= 0) {
403	                    setSaidaAvulsaLoading(false);
404	                    playErrorSound();
405	                    toast({
406	                        title: "Estoque zerado",
407	                        description: `Não há saldo de "${etiqueta.produto_nome}" nesta loja. Não dá pra retirar.`,
408	                        variant: "destructive",
409	                    });
410	                    return;
411	                }
412	                if (qtd > saldoEstoque) {
413	                    setSaidaAvulsaLoading(false);
414	                    playErrorSound();
415	                    toast({
416	                        title: "Estoque insuficiente",
417	                        description: `Estoque tem ${saldoEstoque} mas você pediu ${qtd}. Ajuste a quantidade.`,
418	                        variant: "destructive",
419	                    });
420	                    return;
421	                }
422	            }
423	            // 1. RPC atômica de retirada (atualiza quantidade_disponivel + status + timeline)
424	            // payload habilita backfill quando etiqueta legacy nao está no banco
425	            const itemRefRpc = scannedItems.find(i => i.data.uid === etiqueta.uid);
426	            // eslint-disable-next-line @typescript-eslint/no-explicit-any
