1	import { useState, useRef, useEffect, useCallback } from 'react';
2	import { X, Camera, Loader2, CheckCircle2 } from 'lucide-react';
3	import { Button } from '@/shared/ui/button';
4	import {
5	  Dialog,
6	  DialogContent,
7	  DialogHeader,
8	  DialogTitle,
9	} from '@/shared/ui/dialog';
10	import { Html5Qrcode } from 'html5-qrcode';
11	import { toast } from 'sonner';
12	import { handleError } from '@/shared/lib/error-handler';
13	import { wideWarn } from '@/shared/lib/telemetry/wide-events';
14	
15	interface ReceiptScannerProps {
16	  isOpen: boolean;
17	  onClose: () => void;
18	  onScan: (data: string) => void;
19	}
20	
21	export function ReceiptScanner({
22	  isOpen,
23	  onClose,
24	  onScan,
25	}: ReceiptScannerProps) {
26	  const [isScanning, setIsScanning] = useState(false);
27	  const [cameras, setCameras] = useState<Array<{ id: string; label: string }>>(
28	    [],
29	  );
30	  const [selectedCamera, setSelectedCamera] = useState<string>('');
31	  const scannerRef = useRef<Html5Qrcode | null>(null);
32	  const scannerRegionId = 'receipt-reader';
33	
34	  // Initialize cameras
35	  useEffect(() => {
36	    if (isOpen) {
37	      Html5Qrcode.getCameras()
38	        .then((devices) => {
39	          if (devices && devices.length) {
40	            setCameras(devices);
41	            // Prefer back camera
42	            const backCamera = devices.find(
43	              (d) =>
44	                d.label.toLowerCase().includes('back') ||
45	                d.label.toLowerCase().includes('traseira'),
46	            );
47	            setSelectedCamera(backCamera ? backCamera.id : devices[0].id);
48	          }
49	        })
50	        .catch((err) => {
51	          handleError(err, { domain: 'logistica', operation: 'getCameras', showToast: false });
52	          toast.error('Erro ao acessar câmeras. Verifique as permissões.');
53	        });
54	    }
55	
56	    return () => {
57	      stopScanner();
58	    };
59	  }, [isOpen]);
60	
61	  const startScanner = useCallback(async () => {
62	    if (!selectedCamera) return;
63	
64	    try {
65	      if (scannerRef.current) {
66	        await stopScanner();
67	      }
68	
69	      const html5QrCode = new Html5Qrcode(scannerRegionId);
70	      scannerRef.current = html5QrCode;
71	
72	      await html5QrCode.start(
73	        selectedCamera,
74	        {
75	          fps: 10,
76	          qrbox: { width: 250, height: 250 },
77	          aspectRatio: 1.0,
78	        },
79	        (decodedText) => {
80	          playSuccessSound();
81	          onScan(decodedText);
82	          // Don't close immediately to allow rapid scanning, or maybe visual feedback?
83	          // For now, let's flash success and keep scanning or let parent decide.
84	          // If we want to close: stopScanner(); onClose();
85	        },
86	        (errorMessage) => {
87	          // ignore errors for each frame
88	        },
89	      );
90	      setIsScanning(true);
91	    } catch (err) {
92	      handleError(err, { domain: 'logistica', operation: 'startScanner', showToast: false });
93	      toast.error('Erro ao iniciar câmera.');
94	      setIsScanning(false);
95	    }
96	  }, [selectedCamera, onScan]);
97	
98	  const stopScanner = async () => {
99	    if (scannerRef.current && scannerRef.current.isScanning) {
100	      try {
101	        await scannerRef.current.stop();
102	        scannerRef.current.clear();
103	      } catch (err) {
104	        handleError(err, { domain: 'logistica', operation: 'stopScanner', showToast: false });
105	      }
106	    }
107	    scannerRef.current = null;
108	    setIsScanning(false);
109	  };
110	
111	  const playSuccessSound = () => {
112	    const audio = new Audio('/sounds/beep.mp3'); // Ensure this asset exists or use a synth
113	    // Fallback synth
114	    if (!audio.canPlayType('audio/mpeg')) {
115	      const ctx = new (
116	        window.AudioContext || (window as any).webkitAudioContext
117	      )();
118	      const osc = ctx.createOscillator();
119	      const gain = ctx.createGain();
120	      osc.connect(gain);
121	      gain.connect(ctx.destination);
122	      osc.frequency.value = 800;
123	      osc.type = 'sine';
124	      gain.gain.setValueAtTime(0.1, ctx.currentTime);
125	      osc.start();
126	      setTimeout(() => osc.stop(), 100);
127	    } else {
128	      audio.play().catch((e) => wideWarn('logistica.audio.playFailed', 'Falha ao reproduzir áudio de sucesso', { domain: 'logistica', attributes: { error: String(e) } }));
129	    }
130	  };
131	
132	  // Auto-start when camera is selected
133	  useEffect(() => {
134	    if (selectedCamera && isOpen && !isScanning) {
135	      // Tiny delay to ensure DOM is ready
136	      setTimeout(() => startScanner(), 100);
137	    }
138	    // eslint-disable-next-line react-hooks/exhaustive-deps
139	  }, [selectedCamera, isOpen, startScanner]);
140	
141	  return (
142	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
143	      <DialogContent data-mia-modal="escanear-recebimento" className="sm:max-w-md bg-black border-zinc-800 text-white p-0 overflow-hidden">
144	        <DialogHeader className="p-4 bg-zinc-900 border-b border-zinc-800 flex flex-row items-center justify-between">
145	          <DialogTitle className="text-lg font-bold flex items-center gap-2">
146	            <Camera className="w-5 h-5 text-emerald-500" />
147	            Escanear Recebimento
148	          </DialogTitle>
149	          {cameras.length > 1 && (
150	            <Button
151	              variant="ghost"
152	              size="sm"
153	              className="h-8 text-xs text-zinc-400"
154	              onClick={() => {
155	                const currentIndex = cameras.findIndex(
156	                  (c) => c.id === selectedCamera,
157	                );
158	                const nextIndex = (currentIndex + 1) % cameras.length;
159	                setSelectedCamera(cameras[nextIndex].id);
160	              }}
161	            >
162	              Trocar Câmera
163	            </Button>
164	          )}
165	        </DialogHeader>
166	
167	        <div className="relative bg-black h-[400px] flex flex-col items-center justify-center">
168	          <div id={scannerRegionId} className="w-full h-full" />
169	
170	          {!isScanning && (
171	            <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-10">
172	              <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
173	              <span className="ml-2 text-zinc-400">Iniciando câmera...</span>
174	            </div>
175	          )}
176	
177	          <div className="absolute bottom-6 left-0 right-0 flex justify-center z-20 pointer-events-none">
178	            <div className="bg-black/60 backdrop-blur-md px-4 py-2 rounded-full text-xs text-white/80 border border-white/10">
179	              Aponte para o QR Code da etiqueta
180	            </div>
181	          </div>
182	        </div>
183	      </DialogContent>
184	    </Dialog>
185	  );
186	}
