82	export function playErrorSound() {
83	  try {
84	    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
85	    const ctx = new Ctx();
86	    const osc = ctx.createOscillator();
87	    const gain = ctx.createGain();
88	    osc.connect(gain);
89	    gain.connect(ctx.destination);
90	    osc.frequency.setValueAtTime(300, ctx.currentTime);
91	    osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
92	    osc.type = "square";
93	    gain.gain.value = 0.1;
94	    osc.start();
95	    osc.stop(ctx.currentTime + 0.3);
96	  } catch { /* ignore */ }
97	}
