148	  eid: string;       // embalagem_id (legacy — catalogo de embalagens)
149	  emb: string;       // unidade interna (un, kg, g, l, ml, sache)
150	  tipo?: string;     // tipo_embalagem (caixa, saco, balde, pote, galao, etc.) — pos-padrao 13/05/2026
151	  qty: number;       // qty interna
