177	/**
178	 * Parse permissivo MULTI-CAMADA — desenhado pra sobreviver a USB scanners
179	 * em Android tablets que ocasionalmente perdem 1 caractere ou inserem prefixo
180	 * desconhecido. Estratégias em ordem (a primeira que retornar JSON válido com
181	 * `p`/`pid` ganha):
182	 *
183	 *  1. Hex puro (formato canônico LabelPrinting.encodeHex)
184	 *  2. Hex com pequeno lixo no meio (>80% hex)
185	 *  3. JSON puro (quando câmera lê o conteúdo direto, ou usuário cola)
186	 *  4. ABNT2 mangled (@ -> ", > -> :, < -> ,, ; -> -)
187	 *  5. RECOVERY: extrair maior substring hex e tentar decodificar
188	 *  6. RECOVERY: hex de length impar — tentar prepend e append cada char hex
189	 *  7. RECOVERY: extrair primeiro JSON-like substring `{...}` do conteúdo
190	 *
191	 * O hook chama isso uma vez por leitura. Custo extra das tentativas só ocorre
192	 * quando o caminho feliz falha — então não impacta o uso normal.
193	 */
194	export function parseQrData(value: string): ScannedPayload | null {
195	  const sanitized = sanitizeScanInput(value);
196	  if (!sanitized) return null;
197	  const lower = sanitized.toLowerCase();
198	
199	  const candidates: Array<() => Record<string, unknown> | null> = [
200	    // 0) UID puro — formato canônico atual do LabelPrinting (QR contém só
201	    //    o UID, dados ficam no banco). 4-32 chars alfanuméricos sem '{'.
202	    //    Curto e robusto contra perda de chars em scanner Android.
203	    () => {
204	      if (sanitized.includes("{")) return null;
205	      if (!/^[0-9a-zA-Z]{4,32}$/.test(sanitized)) return null;
206	      // Devolve só o UID — o consumer faz lookup em etiquetas_qr pra preencher
207	      // produto, lote, etc. Sem isso, o resto do parser tenta tratar como hex
208	      // longo e falha (length impar, chars insuficientes pra JSON).
209	      return { u: sanitized, p: "", l: "", c: "", n: "", q: 1 };
210	    },
211	
212	    // 1) Hex puro (legacy — etiquetas geradas antes da mudança pra UID-only)
213	    () => (/^[0-9a-f]+$/.test(lower) && lower.length > 32 ? tryHex(lower) : null),
214	
215	    // 2) Hex com lixo do meio (>80% hex)
216	    () => {
217	      const hexOnly = lower.replace(/[^0-9a-f]/g, "");
218	      if (hexOnly.length < 20 || hexOnly.length / lower.length < 0.8) return null;
219	      return tryHex(hexOnly);
220	    },
221	
222	    // 3) JSON puro (câmera ou paste manual)
223	    () => {
224	      if (!sanitized.includes("{")) return null;
225	      try {
226	        const start = sanitized.indexOf("{");
227	        const end = sanitized.lastIndexOf("}");
228	        if (start < 0 || end <= start) return null;
229	        const json = sanitized.slice(start, end + 1);
230	        const parsed = JSON.parse(json);
231	        return typeof parsed === "object" && parsed !== null ? parsed : null;
232	      } catch { return null; }
233	    },
234	
235	    // 4) ABNT2 mangled
236	    () => {
237	      try {
238	        let r = sanitized;
239	        if (!r.startsWith("{")) r = `{${r}}`;
240	        r = r.replace(/@/g, '"').replace(/>/g, ":").replace(/</g, ",").replace(/;/g, "-");
241	        const parsed = JSON.parse(r);
242	        return typeof parsed === "object" && parsed !== null ? parsed : null;
243	      } catch { return null; }
244	    },
245	
246	    // 5) Maior substring hex (em caso de prefix/suffix de protocolo)
247	    () => {
248	      const hexRuns = lower.match(/[0-9a-f]{40,}/g);
249	      if (!hexRuns) return null;
250	      // Tenta a maior primeiro
251	      hexRuns.sort((a, b) => b.length - a.length);
252	      for (const run of hexRuns) {
253	        const result = tryHex(run);
254	        if (result) return result;
255	      }
256	      return null;
257	    },
258	
259	    // 6) Hex impar — char perdido. Tenta prepend e append de cada hex.
260	    () => {
261	      if (lower.length % 2 !== 1) return null;
262	      const onlyHex = /^[0-9a-f]+$/.test(lower);
263	      if (!onlyHex) return null;
264	      const hexChars = "0123456789abcdef";
265	      for (const c of hexChars) {
266	        const fwd = tryHex(c + lower);
267	        if (fwd) return fwd;
268	        const back = tryHex(lower + c);
269	        if (back) return back;
270	      }
271	      return null;
272	    },
273	
274	    // 7) Extrai primeiro JSON-like {...} de qualquer lugar do conteúdo
275	    () => {
276	      const start = sanitized.indexOf("{");
277	      const end = sanitized.lastIndexOf("}");
278	      if (start < 0 || end <= start) return null;
279	      try {
280	        const parsed = JSON.parse(sanitized.slice(start, end + 1));
281	        return typeof parsed === "object" && parsed !== null ? parsed : null;
282	      } catch { return null; }
283	    },
284	
285	    // 8) ÚLTIMO RECURSO: hex degradado decodifica mas o JSON tá corrompido
286	    //    (chars perdidos / trocados — Chrome Android perde eventos em rate alto).
287	    //    Em vez de exigir JSON válido, EXTRAI os campos diretamente via regex
288	    //    do CONTEÚDO DECODIFICADO. Funciona mesmo se faltam chars no meio,
289	    //    se `-` virou `=`, se aspa quebrou, etc. Suficiente pra montar payload.
290	    () => {
291	      // Tenta decodificar hex (puro ou degradado) pra obter o conteúdo string
292	      let content = "";
293	      if (/^[0-9a-f]+$/.test(lower) && lower.length > 20) {
294	        try { content = decodeHex(lower.length % 2 === 0 ? lower : lower.slice(0, -1)); } catch { return null; }
295	      } else {
296	        const hexOnly = lower.replace(/[^0-9a-f]/g, "");
297	        if (hexOnly.length > 20) {
298	          try { content = decodeHex(hexOnly.length % 2 === 0 ? hexOnly : hexOnly.slice(0, -1)); } catch { /* ignore */ }
299	        }
300	      }
301	      // Se hex falhou ou não é hex, tenta o sanitized direto (caso JSON puro corrompido)
302	      if (!content) content = sanitized;
303	      if (!content) return null;
304	
305	      // Extrai cada campo via regex tolerante (aceita chars não-aspas no lugar de aspas)
306	      // ["']?p["']?\s*:\s*["']?(VALOR)["']?
307	      const grabStr = (key: string): string | null => {
308	        const re = new RegExp(`["'\`]?${key}["'\`]?\\s*[:=]\\s*["'\`]?([^"',}\\]\\s]+?)["'\`]?(?:\\s*[,}]|$)`, "i");
309	        const m = re.exec(content);
310	        return m ? m[1] : null;
311	      };
312	      const grabNum = (key: string): number | null => {
313	        const re = new RegExp(`["'\`]?${key}["'\`]?\\s*[:=]\\s*(\\d+)`, "i");
314	        const m = re.exec(content);
315	        return m ? Number(m[1]) : null;
316	      };
317	
318	      // Aceita chave longa (pid/lid/qty/emb) ou curta (p/l/q/n).
319	      const pid = grabStr("pid") ?? grabStr("p");
320	      if (!pid || !/^\d+$/.test(pid)) return null;
321	
322	      const uid = grabStr("uid") ?? grabStr("u") ?? "";
323	      const lid = grabStr("lid") ?? grabStr("l") ?? "";
324	      const lote = grabStr("lote") ?? grabStr("c") ?? "";
325	      const emb = grabStr("emb") ?? grabStr("n") ?? "";
326	      const qty = grabNum("qty") ?? grabNum("q") ?? 1;
327	
328	      return { pid, uid, lid, lote, emb, qty };
329	    },
330	  ];
331	
332	  let raw: Record<string, unknown> | null = null;
333	  for (const strategy of candidates) {
334	    const r = strategy();
335	    if (r && isMommaPayload(r)) { raw = r; break; }
336	  }
337	  if (!raw) return null;
338	
339	  const get = (a: string, b: string) => (raw![a] ?? raw![b] ?? "") as string | number;
340	  const tipoRaw = String(raw!["tipo"] ?? raw!["t"] ?? "").trim();
341	  return {
342	    pid: String(get("pid", "p")),
343	    lid: String(get("lid", "l")),
344	    lote: String(get("lote", "c")),
345	    val: String(get("val", "v")),
346	    eid: String(get("eid", "e")),
347	    emb: String(get("emb", "n")),
348	    tipo: tipoRaw || undefined,
349	    qty: Number(raw!["qty"] ?? raw!["q"] ?? 1),
350	    uid: String(get("uid", "u")),
351	  };
352	}
